const { readFileSync } = await import('node:fs');
if (!globalThis.input || typeof globalThis.input.image_path !== 'string') {
  throw new Error('Missing required input: image_path');
}
globalThis.imagePath = globalThis.input.image_path;

const { readFileSync, writeFileSync } = await import('node:fs');
const { PDFDocument } = await import('pdf-lib');
const imgBytes = readFileSync(globalThis.imagePath);
const pdfDoc = await PDFDocument.create();
let img;
if (globalThis.imagePath.toLowerCase().endsWith('.png')) {
  img = await pdfDoc.embedPng(imgBytes);
} else {
  img = await pdfDoc.embedJpg(imgBytes);
}
const page = pdfDoc.addPage([img.width, img.height]);
page.drawImage(img, { x: 0, y: 0, width: img.width, height: img.height });
const pdfBytes = await pdfDoc.save();
const outPath = '/tmp/output.pdf';
writeFileSync(outPath, pdfBytes);
globalThis.pdfPath = outPath;
